/// 战利品批次
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct LootBatch {
    pub batch_id: Uuid,
    pub player_id: String,
    pub loot_table_id: i32,
    pub rolled_items: Vec<String>,
    pub claimed: bool,
    pub rolled_at: DateTime<Utc>,
}

