impl InMemoryEconomyV3Repository {
    pub fn new() -> Self {
        Self::default()
    }

    /// 注入 9 个 holiday_* 种子模板 (W41 增广度)
    /// 覆盖 Holiday / Signin / Achievement / Battlepass / Return / Invite / LevelReward / Daily / Weekly 9 大类
    /// 用法: repo.seed_9_holiday_templates(); 测试或本地启动时调用
    pub fn seed_9_holiday_templates(&mut self) {
        let now = Utc::now();
        let seeds = nine_holiday_seed_templates(now);
        for (id, t) in seeds {
            self.activity_templates.insert(id, t);
        }
    }

    /// 种子玩家 ID —— 必须与
    /// `D:\rgs-flash-mock\postgres\seed-flash-test-data.sql` 里 accounts.player_id
    /// 保持一致 (rgs-shim 硬编码的 player UUID)。
    const SEED_PLAYER_ID: &'static str = "11111111-1111-1111-1111-111111111111";

    /// 注入基础游戏内容 (2026-10-03 实装)
    ///
    /// ## 为什么需要
    ///
    /// `EconomyGrpcService::new()` 里 `InMemoryEconomyV3Repository::new()` 是
    /// `Default::default()` —— **全空**, 而且 `seed_9_holiday_templates` 此前
    /// 只在 `shop_service_tests.rs` 里被调用, 生产启动路径从不灌任何内容。
    /// 后果是所有 v3 功能 (商店 / 神秘商店 / 兑换 / 点数商店 / 礼包码 / 掉落)
    /// 在端到端探测时一律 `NOT_FOUND`:
    ///
    ///   not found: ShopItem with id 1-x
    ///   not found: MysteryShop with id 1
    ///   not found: ExchangeShop with id 1
    ///   not found: PointShopItem with id 1-x
    ///   not found: GiftCode with id x-1
    ///   not found: LootTable with id 1
    ///
    /// handler 全都写好了, 只是查不到行 —— 与 v1 那 73 个 `Err(Status::unimplemented)`
    /// 是**两个独立的缺口**, 不要混为一谈。
    ///
    /// ## 覆盖范围
    ///
    /// | 仓字段          | 覆盖的 RPC                                              |
    /// |-----------------|---------------------------------------------------------|
    /// | shop_items      | ShopList / ShopBuy / ShopRefresh                          |
    /// | mystery_shops   | MysteryShopList / MysteryShopBuy / Refresh / Unlock       |
    /// | exchange_shops  | ExchangeList / ExchangeDo / **PointShopList / PointShopBuy** |
    /// | player_points   | PointShopBuy (点数余额; 否则扣费必失败)                    |
    /// | gift_codes      | GiftCodeRedeem / GiftCodeQuery                            |
    /// | loot_tables     | LootRoll / LootClaim                                      |
    ///
    /// 注意 PointShopBuy 是 `exchange_do` 的别名 (`shop_service.rs:1878`):
    /// 它按 `exchange_shops` 里 `cost_currency == point_type` 且含该 item 反查
    /// exchange_id, 所以种一次 exchange_shops 就能同时喂饱兑换和点数商店两条路。
    ///
    /// ## 设计取舍
    ///
    /// 数值刻意用**一眼可辨的非占位值** (价格 100/200/500, 库存 99/199),
    /// 跟 UUID 哈希或 1/18 那种占位值区分开 —— 探测报告里看到 500 金币就知道
    /// 是这份种子, 而不是别的路径塞进来的。
    ///
    /// 幂等: 全部走 HashMap insert, 重复调用只是覆盖成同值。
    pub fn seed_game_content(&mut self) {
        let now = Utc::now();

        // ---- 道具工厂: 免得每个 item 写一遍 9 个字段 ----
        let item = |item_id: &str, name: &str, price: i64, cur: i32, stock: i32| ShopItemEntity {
            item_id: item_id.to_string(),
            sku: format!("SKU-{item_id}"),
            name: name.to_string(),
            price_amount: price,
            price_currency: cur,
            stock,
            vip_level_required: 0,
            level_required: 1,
            limit_per_player: 10,
            tag: "seed".to_string(),
        };

        // ---- 普通商店 (shop_id 1) ----
        for (iid, name, price) in [
            ("gold-pack-small", "金币包·小", 100i64),
            ("gold-pack-large", "金币包·大", 500),
            ("diamond-pack", "钻石包", 200),
            ("stamina-refill", "体力药水", 50),
        ] {
            self.shop_items
                .insert((1, iid.to_string()), item(iid, name, price, 1, 199));
        }

        // ---- 神秘商店 (shop_id 1) ----
        self.mystery_shops.insert(
            1,
            MysteryShop {
                mystery_shop_id: 1,
                unlock_level: 1,
                refresh_cost: 100,
                max_refresh: 3,
            },
        );
        // 神秘商店还有一层 **玩家维度** 状态 (mystery_states): MysteryShopList 先查
        // mystery_shops 拿配置, 再按 (player_id, shop_id) 查状态, 查不到就
        // NOT_FOUND "MysteryShopState with id {player_id}-{shop_id}"。
        // 这里给种子玩家建一条已解锁、已刷出商品的初始状态。
        self.mystery_states.insert(
            (Self::SEED_PLAYER_ID.to_string(), 1),
            MysteryShopState {
                player_id: Self::SEED_PLAYER_ID.to_string(),
                mystery_shop_id: 1,
                unlocked: true,
                unlocked_at: Some(now),
                refresh_count: 0,
                refreshed_at: now,
                current_items: vec![
                    item("myst-1", "神秘商品·一", 150, 1, 5),
                    item("myst-2", "神秘商品·二", 250, 1, 3),
                ],
            },
        );

        // ---- 兑换商店 ----
        // exchange_id 1: cost_currency=1 (金币) → ExchangeList / ExchangeDo
        self.exchange_shops.insert(
            1,
            ExchangeShop {
                exchange_id: 1,
                cost_currency: 1,
                items: vec![
                    item("ex-fragment", "角色碎片", 300, 1, -1),
                    item("ex-diamond", "钻石兑换", 1000, 1, 50),
                ],
            },
        );
        // exchange_id 2: cost_currency=2 (点数) → PointShopBuy 靠这条反查
        // (shop_service.rs:1880 按 cost_currency == point_type 匹配)
        self.exchange_shops.insert(
            2,
            ExchangeShop {
                exchange_id: 2,
                cost_currency: 2,
                items: vec![
                    item("pt-card", "点卡", 10, 2, -1),
                    item("pt-token", "代币", 25, 2, 99),
                ],
            },
        );

        // ---- 礼包码 (code, server_id) ----
        // 有效期跨now, 否则 GiftCodeRedeem 会判过期
        self.gift_codes.insert(
            ("FLASHMOCK2026".to_string(), 1),
            GiftCode {
                code: "FLASHMOCK2026".to_string(),
                server_id: 1,
                reward_template: "gold:5000,diamond:100".to_string(),
                valid_from: now - chrono::Duration::days(1),
                valid_to: now + chrono::Duration::days(365),
                max_uses: 1000,
                current_uses: 0,
            },
        );

        // ---- 掉落表 (LootRoll 必查 loot_table_id) ----
        self.loot_tables.insert(
            1,
            LootTable {
                loot_table_id: 1,
                entries: vec![
                    LootEntry { item_id: "drop-common".to_string(), weight: 70, rarity: 1 },
                    LootEntry { item_id: "drop-rare".to_string(), weight: 25, rarity: 3 },
                    LootEntry { item_id: "drop-legendary".to_string(), weight: 5, rarity: 5 },
                ],
            },
        );
    }
}

// ============================================================================
// W41 增广度: 9 个 holiday_* 种子模板 (per 9/4 MD §4 数据驱动反例)
// ============================================================================
//
// 设计: 1 套 ActivityService + 1 个 ActivityType 枚举涵盖 9 个 holiday 变体
// 9 个具体 holiday_* 活动以模板形式注入, ActivityType 区分种类
// 1 个 holiday_*_request/_response = 1 个模板 entry, 不是 9 套 RPC
//
// 9 个 holiday 命名 (per [游戏A]运营活动盘点):
// 1. 春节 (Spring Festival)    - Holiday
// 2. 夏日嘉年华 (Summer Carnival) - Holiday
// 3. 万圣节 (Halloween)        - Holiday
// 4. 圣诞节 (Christmas)        - Holiday
// 5. 新年 (New Year)          - Holiday
// 6. 周年庆 (Anniversary)      - Holiday
// 7. 中秋 (Mid-Autumn)        - Holiday
// 8. 情人节 (Valentine)        - Holiday
// 9. 感恩节 (Thanksgiving)     - Holiday
//
// 加上 8 个 ActivityType 变体 (Signin/Achievement/Battlepass/Return/Invite/LevelReward/Daily/Weekly)
// = 9 holiday + 8 other = 17 模板种子, 跨整年运营节奏

/// 9 个 holiday_* 种子模板生成 (per 2026-09-05 Phase 2 economy 9 活动运营)
pub fn nine_holiday_seed_templates(now: DateTime<Utc>) -> Vec<(i32, ActivityTemplateEntity)> {
    vec![
        (1001, make_holiday_template(1001, "Spring Festival",  ActivityType::Holiday,     now, 14, 1)),
        (1002, make_holiday_template(1002, "Summer Carnival",   ActivityType::Holiday,     now, 30, 5)),
        (1003, make_holiday_template(1003, "Halloween",         ActivityType::Holiday,     now,  7, 9)),
        (1004, make_holiday_template(1004, "Christmas",         ActivityType::Holiday,     now, 14, 11)),
        (1005, make_holiday_template(1005, "New Year",          ActivityType::Holiday,     now,  7, 0)),
        (1006, make_holiday_template(1006, "Anniversary",       ActivityType::Holiday,     now, 14, 6)),
        (1007, make_holiday_template(1007, "Mid-Autumn",        ActivityType::Holiday,     now,  7, 8)),
        (1008, make_holiday_template(1008, "Valentine",         ActivityType::Holiday,     now,  7, 1)),
        (1009, make_holiday_template(1009, "Thanksgiving",      ActivityType::Holiday,     now,  7, 10)),
    ]
}

/// 构造单个 holiday 模板 (W41 helper)
fn make_holiday_template(
    activity_id: i32,
    name: &str,
    activity_type: ActivityType,
    starts_at: DateTime<Utc>,
    duration_days: i64,
    start_month: u32,
) -> ActivityTemplateEntity {
    ActivityTemplateEntity {
        activity_id,
        name: name.to_string(),
        activity_type,
        starts_at,
        ends_at: starts_at + Duration::days(duration_days),
        max_progress: 100,
        min_level: 1,
        max_level: 0,
        template_json: format!(
            r#"{{"reward_tiers":[1,5,10,20,50,100],"conditions":["login","purchase","complete_quest"],"start_month":{start_month}}}"#,
            start_month = start_month
        ),
        enabled: true,
    }
}

